    font-size: 17px;
    font-weight: bold;
    cursor: pointer;
    padding: 15px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    color: #222;
    transition: 0.3s;
}
.eon8-live-page .faq-question:hover {
