    max-height: 0;
    overflow: hidden;
    transition: 0.4s ease;
    padding: 0 15px;
}
.eon8-live-page .faq-answer p {
    font-size: 15px;
    color: #555;
    line-height: 1.6;
    margin-bottom: 15px;
}
.eon8-live-page .faq-item.active .faq-answer {
    max-height: 200px;
}
.eon8-live-page .faq-item.active .faq-icon {
